using System;using System.IO;using System.Linq;using System.Web.Script.Serialization;using LestingCraft.Story;
class CheckGuardian
{
 static void Main(string[] args){var d=new JavaScriptSerializer{MaxJsonLength=4000000}.Deserialize<GuardianDefinition>(File.ReadAllText(args[0]));var m=GuardianSculpture.CreateGeometry(d);if(m.vertices.Count==0||m.vertices.Count%4!=0||m.triangles.Count!=m.vertices.Count/4*6)throw new Exception("mesh topology");if(m.normals.Count!=m.vertices.Count||m.uv.Count!=m.vertices.Count||m.materials.Count!=m.vertices.Count||m.colors.Count!=m.vertices.Count)throw new Exception("attribute mismatch");foreach(var i in m.triangles)if(i<0||i>=m.vertices.Count)throw new Exception("invalid index");foreach(var v in m.vertices)if(float.IsNaN(v.x)||v.y<0||v.y>7.2)throw new Exception("invalid extent");var pair=new GuardianDefinition{unit=.1f,name="fixture",palette=new[]{d.palette[0]},cells=new[]{0,0,0,0,1,0,0,0}};if(GuardianSculpture.CreateGeometry(pair).vertices.Count!=40)throw new Exception("hidden adjacent faces not culled");Console.WriteLine("PASS actual managed C# sculpture geometry: "+d.cells.Length/4+" voxels, "+m.vertices.Count/4+" exposed quads, "+m.vertices.Count+" vertices, "+m.triangles.Count/3+" triangles; adjacent faces culled, valid indices/attributes/bounds. Native Mesh upload/URP not executed.");}
}
